// Extraer payload recibido desde TechCare PHP
const data = $input.first().json.body || $input.first().json;

const evento = data.evento || 'ticket_creado';
const ticketId = data.ticket_id || 'N/A';
const nombre = data.nombre || 'Estimado(a) Usuario(a)';
const email = data.email || '';
const empresa = data.empresa || 'Particular';
const asunto = data.asunto || 'Sin Asunto';
const tipo = data.tipo_problema || 'SOFTWARE';
const prioridad = (data.prioridad || 'media').toUpperCase();
const mensaje = data.mensaje || '';
const fecha = data.timestamp || new Date().toLocaleString();
const urlSeguimiento = data.url_seguimiento || 'http://127.0.0.1:8000/index.php?action=formulario';
const urlFeedbackSi = data.url_feedback_si || urlSeguimiento;
const urlFeedbackNo = data.url_feedback_no || urlSeguimiento;
const motivoDevolucion = data.motivo_devolucion || 'El usuario indicó que la solución no resolvió la incidencia.';

let asuntoEmail = '';
let htmlEmail = '';

if (evento === 'ticket_resuelto') {
  // ==========================================
  // PLANTILLA: TICKET RESUELTO CON ENCUESTA CSAT (VERDE)
  // ==========================================
  asuntoEmail = `[TechCare Soporte TI] ✅ Solicitud #${ticketId} RESUELTA - ${asunto}`;

  htmlEmail = `
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Solicitud Resuelta - TechCare Soporte TI</title>
  <style>
    body { font-family: 'Segoe UI', Helvetica, Arial, sans-serif; background-color: #f1f5f9; margin: 0; padding: 20px; color: #1e293b; }
    .container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1); border: 1px solid #e2e8f0; }
    .header { background: linear-gradient(135deg, #064e3b 0%, #059669 100%); color: #ffffff; padding: 28px 24px; text-align: center; }
    .header h1 { margin: 0; font-size: 24px; font-weight: 700; letter-spacing: 0.5px; }
    .header p { margin: 6px 0 0 0; font-size: 13px; color: #a7f3d0; }
    .content { padding: 30px 24px; }
    .saludo { font-size: 18px; font-weight: 600; color: #064e3b; margin-bottom: 12px; }
    .intro { font-size: 14.5px; line-height: 1.6; color: #334155; margin-bottom: 24px; }
    .card { background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 8px; padding: 18px; margin-bottom: 24px; }
    .card-title { font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px; color: #059669; font-weight: 700; margin-bottom: 12px; border-bottom: 1px solid #e2e8f0; padding-bottom: 6px; }
    .badge-resuelto { display: inline-block; padding: 4px 12px; border-radius: 9999px; font-size: 12px; font-weight: 700; color: #ffffff; background-color: #10b981; }
    .feedback-box { background: #f0fdf4; border: 2px dashed #059669; border-radius: 10px; padding: 20px; text-align: center; margin: 26px 0; }
    .btn-si { background: #059669; color: #ffffff !important; padding: 11px 20px; text-decoration: none; border-radius: 6px; font-weight: 700; font-size: 13.5px; display: inline-block; box-shadow: 0 2px 4px rgba(5,150,105,0.3); margin: 4px; }
    .btn-no { background: #dc2626; color: #ffffff !important; padding: 11px 20px; text-decoration: none; border-radius: 6px; font-weight: 700; font-size: 13.5px; display: inline-block; box-shadow: 0 2px 4px rgba(220,38,38,0.3); margin: 4px; }
    .footer { background: #f8fafc; border-top: 1px solid #e2e8f0; padding: 20px 24px; text-align: center; font-size: 12px; color: #94a3b8; line-height: 1.5; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🎉 ¡Solicitud de Soporte Resuelta!</h1>
      <p>TechCare Soporte TI — Mesa de Ayuda Inteligente</p>
    </div>
    <div class="content">
      <div class="saludo">¡Hola, ${nombre}! 👋</div>
      <div class="intro">
        Nos complace informarte que tu solicitud de soporte técnico <strong>#${ticketId}</strong> ha sido marcada como <strong>RESUELTA</strong> por nuestro equipo de ingenieros de TI.
      </div>

      <div class="card">
        <div class="card-title">Resumen del Caso Atendido</div>
        <table style="width: 100%; border-collapse: collapse; font-size: 14px;">
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Número de Ticket:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;"><strong>#${ticketId}</strong></td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Asunto:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;">${asunto}</td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Categoría:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;">${tipo}</td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Estado Final:</strong></td>
            <td style="padding: 5px 0; text-align: right;"><span class="badge-resuelto">RESUELTO</span></td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Fecha de Cierre:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;">${fecha}</td>
          </tr>
        </table>
      </div>

      <!-- BLOQUE INTERACTIVO CSAT Y REAPERTURA AUTOMÁTICA -->
      <div class="feedback-box">
        <h3 style="margin: 0 0 6px 0; color: #064e3b; font-size: 16px; font-weight: 700;">¿Se solucionó tu incidencia de forma satisfactoria?</h3>
        <p style="margin: 0 0 16px 0; color: #475569; font-size: 13px;">Tu confirmación nos permite auditar la calidad del servicio de TI:</p>
        <div style="text-align: center;">
          <a href="${urlFeedbackSi}" class="btn-si" target="_blank">
            ✅ Sí, quedó resuelto (Calificar)
          </a>
          <a href="${urlFeedbackNo}" class="btn-no" target="_blank">
            ❌ No, sigo con problemas (Devolver)
          </a>
        </div>
      </div>

      <div style="text-align: center; margin-top: 20px;">
        <a href="${urlSeguimiento}" style="color: #64748b; font-size: 13px; text-decoration: underline;" target="_blank">Consultar historial en el Portal</a>
      </div>
    </div>
    <div class="footer">
      Gracias por confiar en <strong>TechCare Soporte TI</strong>.<br>
      Automatización de calidad y seguimiento generada vía <strong>n8n</strong>.
    </div>
  </div>
</body>
</html>
`;

} else if (evento === 'ticket_devuelto') {
  // ==========================================
  // PLANTILLA: TICKET DEVUELTO / REABIERTO (ALERTA ROJA)
  // ==========================================
  asuntoEmail = `[TechCare ALERTA] 🚨 Ticket #${ticketId} DEVUELTO por el Usuario - Prioridad ALTA`;

  htmlEmail = `
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Ticket Devuelto - TechCare Soporte TI</title>
  <style>
    body { font-family: 'Segoe UI', Helvetica, Arial, sans-serif; background-color: #fef2f2; margin: 0; padding: 20px; color: #1e293b; }
    .container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 6px rgba(0,0,0,0.1); border: 1px solid #fecaca; }
    .header { background: linear-gradient(135deg, #991b1b 0%, #dc2626 100%); color: #ffffff; padding: 26px 24px; text-align: center; }
    .header h1 { margin: 0; font-size: 22px; font-weight: 700; }
    .content { padding: 26px 24px; }
    .badge-devuelto { background: #dc2626; color: #ffffff; padding: 4px 12px; border-radius: 9999px; font-weight: 700; font-size: 12px; }
    .footer { background: #f8fafc; border-top: 1px solid #e2e8f0; padding: 18px; text-align: center; font-size: 12px; color: #94a3b8; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🚨 Alerta de Ticket Devuelto / Reabierto</h1>
      <p style="margin: 4px 0 0 0; color: #fecaca; font-size: 13px;">Notificación de Atención Prioritaria para el Equipo de Soporte</p>
    </div>
    <div class="content">
      <p style="font-size: 15px; color: #1e293b;">
        El usuario <strong>${nombre}</strong> (<em>${email}</em>) ha indicado que el problema <strong>NO quedó solucionado</strong> y ha reabierto la incidencia <strong>#${ticketId}</strong>.
      </p>
      <div style="background: #fef2f2; border: 1px solid #fca5a5; border-radius: 8px; padding: 16px; margin: 18px 0;">
        <strong style="color: #991b1b;">Motivo / Observación del Usuario:</strong>
        <p style="margin: 6px 0 0 0; color: #7f1d1d; font-style: italic;">"${motivoDevolucion}"</p>
      </div>
      <div style="text-align: center; margin: 24px 0;">
        <span class="badge-devuelto">NUEVA PRIORIDAD: ALTA / CRÍTICA</span>
      </div>
    </div>
    <div class="footer">
      Mesa de Ayuda <strong>TechCare Soporte TI</strong> &bull; Sistema de Gestión de Calidad n8n
    </div>
  </div>
</body>
</html>
`;

} else {
  // ==========================================
  // PLANTILLA: TICKET CREADO (AZUL / RECEPCIÓN)
  // ==========================================
  asuntoEmail = `[TechCare Soporte TI] Solicitud #${ticketId} Recibida - ${asunto}`;

  let colorPrioridad = '#3b82f6';
  if (prioridad === 'CRITICA' || prioridad === 'CRÍTICA') colorPrioridad = '#ef4444';
  else if (prioridad === 'ALTA') colorPrioridad = '#f59e0b';
  else if (prioridad === 'BAJA') colorPrioridad = '#10b981';

  htmlEmail = `
<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <title>Confirmación de Solicitud - TechCare Soporte TI</title>
  <style>
    body { font-family: 'Segoe UI', Helvetica, Arial, sans-serif; background-color: #f1f5f9; margin: 0; padding: 20px; color: #1e293b; }
    .container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.1); border: 1px solid #e2e8f0; }
    .header { background: linear-gradient(135deg, #0f172a 0%, #1e3a8a 100%); color: #ffffff; padding: 28px 24px; text-align: center; }
    .header h1 { margin: 0; font-size: 24px; font-weight: 700; letter-spacing: 0.5px; }
    .header p { margin: 6px 0 0 0; font-size: 13px; color: #93c5fd; }
    .content { padding: 30px 24px; }
    .saludo { font-size: 18px; font-weight: 600; color: #0f172a; margin-bottom: 12px; }
    .intro { font-size: 14.5px; line-height: 1.6; color: #475569; margin-bottom: 24px; }
    .card { background: #f8fafc; border: 1px solid #cbd5e1; border-radius: 8px; padding: 18px; margin-bottom: 24px; }
    .card-title { font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px; color: #64748b; font-weight: 700; margin-bottom: 12px; border-bottom: 1px solid #e2e8f0; padding-bottom: 6px; }
    .badge-prio { display: inline-block; padding: 3px 10px; border-radius: 9999px; font-size: 12px; font-weight: 700; color: #ffffff; background-color: ${colorPrioridad}; }
    .mensaje-box { background: #ffffff; border-left: 4px solid #3b82f6; padding: 12px 14px; margin-top: 10px; font-style: italic; color: #334155; font-size: 13.5px; border-radius: 0 4px 4px 0; }
    .notice-box { background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 8px; padding: 14px 16px; margin-bottom: 24px; font-size: 13.5px; color: #1e40af; line-height: 1.5; }
    .btn-container { text-align: center; margin: 28px 0 16px 0; }
    .btn { background: #2563eb; color: #ffffff !important; padding: 12px 28px; text-decoration: none; border-radius: 6px; font-weight: 600; font-size: 14px; display: inline-block; box-shadow: 0 2px 4px rgba(37,99,235,0.3); }
    .footer { background: #f8fafc; border-top: 1px solid #e2e8f0; padding: 20px 24px; text-align: center; font-size: 12px; color: #94a3b8; line-height: 1.5; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🛡️ TechCare Soporte TI</h1>
      <p>Mesa de Ayuda Inteligente & Analítica de Incidentes</p>
    </div>
    <div class="content">
      <div class="saludo">¡Hola, ${nombre}! 👋</div>
      <div class="intro">
        Confirmamos que tu solicitud de soporte técnico <strong>#${ticketId}</strong> ha sido recibida correctamente en nuestro sistema.
      </div>

      <div class="notice-box">
        <strong>ℹ️ Compromiso de Atención:</strong><br>
        Nuestro equipo de ingenieros de TI ya se encuentra evaluando los detalles de tu caso. <strong>Nos pondremos en contacto contigo por este mismo medio tan pronto como el ticket haya sido resuelto</strong> o en caso de requerir información adicional.
      </div>

      <div class="card">
        <div class="card-title">Resumen de la Solicitud Registrada</div>
        <table style="width: 100%; border-collapse: collapse; font-size: 14px;">
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Número de Ticket:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;"><strong>#${ticketId}</strong></td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Asunto:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;">${asunto}</td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Categoría:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;">${tipo}</td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Prioridad:</strong></td>
            <td style="padding: 5px 0; text-align: right;"><span class="badge-prio">${prioridad}</span></td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Empresa / Área:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;">${empresa}</td>
          </tr>
          <tr>
            <td style="padding: 5px 0; color: #64748b;"><strong>Fecha y Hora:</strong></td>
            <td style="padding: 5px 0; color: #0f172a; text-align: right;">${fecha}</td>
          </tr>
        </table>
        <div style="margin-top: 12px;">
          <span style="font-size: 12px; color: #64748b; font-weight: 600;">Descripción enviada:</span>
          <div class="mensaje-box">${mensaje}</div>
        </div>
      </div>

      <div class="btn-container">
        <a href="${urlSeguimiento}" class="btn" target="_blank">Consultar Historial de Mis Solicitudes</a>
      </div>
    </div>
    <div class="footer">
      Este es un correo automático generado por el flujo de automatización de <strong>TechCare Soporte TI</strong> vía <strong>n8n</strong>.<br>
      Por favor no respondas directamente a este mensaje.
    </div>
  </div>
</body>
</html>
`;
}

return {
  evento: evento,
  ticket_id: ticketId,
  nombre: nombre,
  email: email,
  asunto_email: asuntoEmail,
  html_email: htmlEmail,
  timestamp: fecha
};
